  <script>
    const TZ = "America/New_York";
    const PAGE = "https://n8n.example.com/webhook/linkedin-posts";
    const sessionKey = "linkedinWebSessionId";
    const boot = window.__INITIAL__ || {};
    const PAGE_SIZE = 25;
    const state = {
      posts: Array.isArray(boot.posts) ? boot.posts : [],
      selectedId: boot.selectedId || null,
      sessionId: getSessionId(),
      page: 1
    };

    function getSessionId() {
      let id = null;
      try { id = localStorage.getItem(sessionKey); } catch (e) {}
      if (!id) {
        id = (crypto.randomUUID && crypto.randomUUID()) || ("web-" + Date.now());
        try { localStorage.setItem(sessionKey, id); } catch (e) {}
      }
      return id;
    }

    function $(id) { return document.getElementById(id); }

    function showBanner(msg, ok) {
      const el = $("banner");
      el.className = "banner " + (ok ? "ok" : "error");
      el.textContent = msg;
    }

    document.querySelectorAll('input[name="session_id"]').forEach((el) => { el.value = state.sessionId; });

    if (boot.idea) $("idea").value = boot.idea;
    if (boot.error) showBanner(boot.error, false);
    else if (boot.message) showBanner(boot.message, true);

    function formatWhen(iso) {
      if (!iso) return "";
      const d = new Date(iso);
      if (Number.isNaN(d.getTime())) return String(iso);
      return new Intl.DateTimeFormat("en-US", {
        timeZone: TZ, month: "short", day: "numeric", hour: "numeric", minute: "2-digit"
      }).format(d) + " ET";
    }

    function toDatetimeLocal(iso) {
      if (!iso) return "";
      const d = new Date(iso);
      if (Number.isNaN(d.getTime())) return "";
      const parts = new Intl.DateTimeFormat("en-US", {
        timeZone: TZ, year: "numeric", month: "2-digit", day: "2-digit",
        hour: "2-digit", minute: "2-digit", hourCycle: "h23"
      }).formatToParts(d);
      const g = (t) => (parts.find((p) => p.type === t) || {}).value;
      return `${g("year")}-${g("month")}-${g("day")}T${g("hour")}:${g("minute")}`;
    }

    function localInputToIso(value) {
      if (!value) throw new Error("Pick a date and time to schedule.");
      const [datePart, timePart] = value.split("T");
      const [y, m, d] = datePart.split("-").map(Number);
      const [hh, mm] = timePart.split(":").map(Number);
      const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
      const pad = (n) => String(n).padStart(2, "0");
      if (tz === TZ) {
        const date = new Date(y, m - 1, d, hh, mm, 0);
        const offsetMin = -date.getTimezoneOffset();
        const sign = offsetMin >= 0 ? "+" : "-";
        const abs = Math.abs(offsetMin);
        const oh = String(Math.floor(abs / 60)).padStart(2, "0");
        const om = String(abs % 60).padStart(2, "0");
        return `${y}-${pad(m)}-${pad(d)}T${pad(hh)}:${pad(mm)}:00${sign}${oh}:${om}`;
      }
      const utcGuess = Date.UTC(y, m - 1, d, hh, mm, 0);
      const probe = new Date();
      const nyNow = new Date(probe.toLocaleString("en-US", { timeZone: TZ }));
      const offsetMs = probe.getTime() - nyNow.getTime();
      const date = new Date(utcGuess + offsetMs);
      const offsetMin = -date.getTimezoneOffset();
      const sign = offsetMin >= 0 ? "+" : "-";
      const abs = Math.abs(offsetMin);
      const oh = String(Math.floor(abs / 60)).padStart(2, "0");
      const om = String(abs % 60).padStart(2, "0");
      const iso = new Date(date.getTime() - date.getTimezoneOffset() * 60000).toISOString().slice(0, 19);
      return iso + sign + oh + ":" + om;
    }

    function statusInfo(post) {
      const status = String(post.status || "").toLowerCase();
      const overdue = status === "scheduled" && post.scheduled_at && Date.parse(post.scheduled_at) < Date.now();
      if (status === "pending_approval") return { key: "needs", label: "Needs review", when: "Waiting on you", needs: true };
      if (status === "failed") return { key: "failed", label: "Failed", when: "Needs retry", needs: true };
      if (status === "publishing") return { key: "publishing", label: "Publishing", when: formatWhen(post.scheduled_at) || "In progress", needs: true };
      if (overdue) return { key: "needs", label: "Overdue", when: formatWhen(post.scheduled_at), needs: true };
      if (status === "scheduled") return { key: "scheduled", label: "Scheduled", when: formatWhen(post.scheduled_at), needs: false };
      if (status === "published") return { key: "published", label: "Published", when: formatWhen(post.published_at || post.scheduled_at), needs: false };
      return { key: "needs", label: status || "Unknown", when: "", needs: false };
    }

    function previewOf(content) {
      return String(content || "").replace(/\s+/g, " ").trim() || "(Empty draft)";
    }

    function selectPost(post) {
      if (!post) return;
      state.selectedId = post.id;
      const idx = filteredPosts().findIndex((p) => String(p.id) === String(post.id));
      if (idx >= 0) state.page = Math.floor(idx / PAGE_SIZE) + 1;
      $("draftEmpty").hidden = true;
      $("editorForm").hidden = false;
      $("draftMeta").textContent = "Draft #" + post.id + " · " + String(post.status || "").replaceAll("_", " ");
      $("draftText").value = post.content || "";
      $("editorDraftId").value = post.id;
      $("editorStatus").value = post.status || "";
      $("generateDraftId").value = String(post.status || "").toLowerCase() === "pending_approval" ? post.id : 0;
      $("scheduleAt").value = toDatetimeLocal(post.scheduled_at) || $("scheduleAt").value;
      const published = String(post.status || "").toLowerCase() === "published";
      $("saveBtn").disabled = published;
      $("scheduleBtn").disabled = published;
      $("draftText").readOnly = published;
      $("draftNotice").textContent = published
        ? "This post is already published, so it can’t be edited or rescheduled here."
        : (String(post.status || "").toLowerCase() === "failed"
          ? "This post failed to publish. Save edits to move it back to review, then schedule it again."
          : "");
      renderQueue();
    }

    function filteredPosts() {
      const hidePublished = $("hidePublished").checked;
      const waitingOnMe = $("waitingOnMe").checked;
      const onlyScheduled = $("onlyScheduled").checked;
      return [...state.posts].filter((p) => {
        const status = String(p.status || "").toLowerCase();
        const info = statusInfo(p);
        if (hidePublished && status === "published") return false;
        if (waitingOnMe && !info.needs) return false;
        if (onlyScheduled && status !== "scheduled") return false;
        return true;
      }).sort((a, b) => {
        const an = statusInfo(a).needs ? 0 : 1;
        const bn = statusInfo(b).needs ? 0 : 1;
        if (an !== bn) return an - bn;
        return Number(b.id) - Number(a.id);
      });
    }

    function renderQueue() {
      const posts = filteredPosts();
      const totalPages = Math.max(1, Math.ceil(posts.length / PAGE_SIZE));
      if (state.page > totalPages) state.page = totalPages;
      if (state.page < 1) state.page = 1;
      const pagePosts = posts.slice((state.page - 1) * PAGE_SIZE, state.page * PAGE_SIZE);
      const needs = posts.filter((p) => statusInfo(p).needs).length;
      const hint = $("needsHint");
      if (needs) {
        hint.hidden = false;
        hint.textContent = "Needs your action (" + needs + ")";
      } else {
        hint.hidden = true;
      }
      $("queue").innerHTML = pagePosts.map((post) => {
        const info = statusInfo(post);
        const selected = String(post.id) === String(state.selectedId) ? " selected" : "";
        const title = previewOf(post.content).replace(/"/g, "&quot;");
        return `<div class="card${selected}" data-id="${post.id}">
          <p class="preview"></p>
          <div class="foot">
            <span>Draft #${post.id}</span>
            <span class="pill ${info.key}">${info.label}</span>
            <span class="when">${info.when}</span>
            <form method="POST" action="https://n8n.example.com/webhook/linkedin-posts" class="delete-form">
              <input type="hidden" name="action" value="delete" />
              <input type="hidden" name="draft_id" value="${post.id}" />
              <button class="btn-delete" type="submit" data-title="${title}">Delete</button>
            </form>
          </div>
        </div>`;
      }).join("") || `<p class="empty">${posts.length ? "No posts on this page." : "No posts match these filters."}</p>`;
      const pager = $("pager");
      pager.hidden = posts.length <= PAGE_SIZE;
      $("pagerLabel").textContent = posts.length
        ? ("Showing " + ((state.page - 1) * PAGE_SIZE + (pagePosts.length ? 1 : 0)) + "–" + ((state.page - 1) * PAGE_SIZE + pagePosts.length) + " of " + posts.length)
        : "";
      $("prevPage").disabled = state.page <= 1;
      $("nextPage").disabled = state.page >= totalPages;
      [...$("queue").querySelectorAll(".card")].forEach((el) => {
        const post = pagePosts.find((p) => String(p.id) === el.getAttribute("data-id"));
        el.querySelector(".preview").textContent = previewOf(post && post.content);
        el.addEventListener("click", (event) => {
          if (event.target.closest(".delete-form")) return;
          selectPost(post);
        });
      });
      [...$("queue").querySelectorAll(".delete-form")].forEach((form) => {
        form.addEventListener("submit", (event) => {
          const btn = form.querySelector(".btn-delete");
          const id = form.querySelector('input[name="draft_id"]').value;
          const ok = confirm("Delete draft #" + id + "? This removes it from the queue and cannot be undone.");
          if (!ok) event.preventDefault();
        });
        form.addEventListener("click", (event) => event.stopPropagation());
      });
    }

    $("editorForm").addEventListener("submit", (event) => {
      const action = event.submitter && event.submitter.getAttribute("data-action") || "save";
      $("editorAction").value = action;
      if (action === "schedule") {
        try {
          $("scheduledAtIso").value = localInputToIso($("scheduleAt").value);
        } catch (err) {
          event.preventDefault();
          showBanner(err.message);
        }
      }
    });

    function resetAndRender() {
      state.page = 1;
      renderQueue();
    }
    $("hidePublished").addEventListener("change", resetAndRender);
    $("waitingOnMe").addEventListener("change", resetAndRender);
    $("onlyScheduled").addEventListener("change", resetAndRender);
    $("prevPage").addEventListener("click", () => { state.page -= 1; renderQueue(); });
    $("nextPage").addEventListener("click", () => { state.page += 1; renderQueue(); });

    renderQueue();
    if (state.selectedId) {
      const current = state.posts.find((p) => String(p.id) === String(state.selectedId));
      if (current) selectPost(current);
    }
  </script>
</body>
</html>
";
